        asset('connector','FinAgent investigations','Planned case-evidence integration. No financial account access is configured.',{'protocol':'REST','endpoint':'','credential_ref':'env:FINAGENT_SERVICE_TOKEN','scopes':['cases:read'],'read_only':True}),
